Method.Source:
    /// <summary>
    /// Validate orderer and manager fields
    /// </summary>
    /// <param name = "p1">The field's id'</param>
    /// <returns>true if the the field is successfully validated; otherwise, false.</returns>
    boolean validateField(FieldId p1)
    {
        boolean ret = next validateField(p1);

        if (ret)
        {
            switch (p1)
            {
                case fieldNum(InventBuyerGroup, METOrderer) : 
                case fieldNum(InventBuyerGroup, METManager) :
                    ret = this.METValidateOrdererAndManager();
                    break;
        
            }
        }
        return ret;
    }

    /// <summary>
    /// Validate orderer and manager are not the same person
    /// </summary>
    /// <returns>true if the orderer and manager are different; otherwise, false.</returns>
    boolean METValidateOrdererAndManager()
    {
        boolean ret = true;
        
        // Do not allow the same Orderer value to be selected in the Manager field for a Buyer group record.
        if (this.METOrderer
        &&  this.METManager
        &&  this.METOrderer == this.METManager)
        {
            ret = checkFailed("@MET:ValidateOrdererManager");
        }

        return ret;
    }

    /// <summary>
    /// A Buyer group value can only be deleted if there are no Purchase orders with that Buyer group populated on the PO headers. Otherwise, the Buyer group cannot be deleted.
    /// </summary>
    /// <returns>true if the buyer group can be deleted; otherwise, false.</returns>
    boolean validateDelete()
    {
        PurchTable  purchTable;
        
        boolean ret = next validateDelete();

        if (ret)
        {
            // Check if Buyer group populated on PO header
            select firstonly RecId from purchTable
                where purchTable.ItemBuyerGroupId == this.Group;

            if (purchTable)
            {
                ret = checkFailed("@MET:BuyerGroupValidateDelete");
            }
        }

        return ret;
    }
